1	const PROCESSING_FEE = 5;
2	
3	// Modifiers are percentages OF THE UNMODIFIED BASE PREMIUM, summed additively
4	// rather than compounded — see the spec's integration examples, where a cursed
5	// sword is 100 base + 50 curse + 10 first insurance (10% of 100, not of 150).
6	//
7	// Rates are kept as integer percents and divided only once, at the point of
8	// use: percentOf(100, 10) is (100 * 10) / 100 = exactly 10, whereas a 0.1
9	// multiplier would give 10.000000000000002 and inflate Math.ceil.
10	const percentOf = (amount: number, percent: number): number => (amount * percent) / 100;
11	
12	const FIRST_INSURANCE_PERCENT = 10;
13	const FOLLOW_UP_PERCENT = 15;
14	const LOYALTY_PERCENT = 20;
15	const LOYALTY_THRESHOLD_YEARS = 2;
16	const CURSE_PERCENT = 50;
17	const HIGH_ENCHANTMENT_PERCENT = 30;
18	const HIGH_ENCHANTMENT_THRESHOLD = 5;
19	
20	// The price list prices each main item individually...
21	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
22	  sword: 100,
23	  amulet: 60,
24	  staff: 80,
25	  potion: 40,
26	};
27	
28	// ...whereas every component is flat-rated at the same base premium,
29	// regardless of which component it is.
30	const COMPONENT_BASE_PREMIUM = 25;
31	const COMPONENT_TYPES = ["rune", "moonstone"];
32	
33	const BLOCK_SIZE = 3;
34	const BLOCK_BASE_PREMIUM = 60;
35	
36	// Claims are settled against the insured VALUE of an item, which the price
37	// list states separately from its base premium.
38	const MAIN_ITEM_INSURANCE_VALUES: Record<string, number> = {
39	  sword: 1000,
40	  amulet: 600,
41	  staff: 800,
42	  potion: 400,
43	};
44	const COMPONENT_INSURANCE_VALUE = 250;
45	
46	const DEDUCTIBLE = 100;
47	const CAP_MULTIPLE = 2;
48	
49	// Claims use their OWN enchantment threshold, distinct from the premium
50	// surcharge's threshold of 5: the spec reimburses damage to items enchanted
51	// to 8 or above at half the damage amount.
52	const REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
53	const HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT = 50;
54	
55	const BASE_PREMIUMS: Record<string, number> = {
56	  ...MAIN_ITEM_BASE_PREMIUMS,
57	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_BASE_PREMIUM])),
58	};
59	
60	const INSURANCE_VALUES: Record<string, number> = {
61	  ...MAIN_ITEM_INSURANCE_VALUES,
62	  ...Object.fromEntries(COMPONENT_TYPES.map((type) => [type, COMPONENT_INSURANCE_VALUE])),
63	};
64	
65	type Item = { type: string; cursed?: boolean; enchantment?: number };
66	type Damage = { itemType: string; amount: number };
67	type Incident = { cause: string; damages: Damage[] };
68	type QuoteStep = { op: "quote"; items: Item[] };
69	type ClaimStep = { op: "claim"; policy: number; incident: Incident };
70	type Step = QuoteStep | ClaimStep;
71	type Customer = { yearsWithMHPCO: number };
72	type Scenario = { customer: Customer; steps: Step[] };
73	
74	const countByType = (items: Item[]): Map<string, number> =>
75	  items.reduce(
76	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
77	    new Map<string, number>(),
78	  );
79	
80	// A building block of exactly 3 alike components is offered at a special
81	// rate; any other count is priced per component.
82	const basePremiumForType = (type: string, count: number): number =>
83	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * BASE_PREMIUMS[type];
84	
85	const stepBasePremium = (step: QuoteStep): number =>
86	  [...countByType(step.items)].reduce(
87	    (total, [type, count]) => total + basePremiumForType(type, count),
88	    0,
89	  );
90	
91	// The PREMIUM-side enchantment rule. Distinct from the claim-side
92	// reimbursement rule below, which keys off the same field at its own, higher
93	// threshold: an item enchanted to 6 is surcharged here but is NOT reimbursed
94	// at half. Components carry no enchantment level at all, so a missing value
95	// is simply not enchanted enough to be surcharged.
96	const isSurchargedForEnchantment = (item: Item): boolean =>
97	  item.enchantment !== undefined && item.enchantment >= HIGH_ENCHANTMENT_THRESHOLD;
98	
99	// Item-specific modifiers apply to the base premium of the affected item,
100	// so they are computed per item rather than from the grouped totals. A
101	// cursed, highly enchanted item takes both surcharges.
102	const itemSurcharge = (item: Item): number => {
103	  const basePremium = BASE_PREMIUMS[item.type];
104	  const curseSurcharge = item.cursed ? percentOf(basePremium, CURSE_PERCENT) : 0;
105	  const enchantmentSurcharge = isSurchargedForEnchantment(item)
106	    ? percentOf(basePremium, HIGH_ENCHANTMENT_PERCENT)
107	    : 0;
108	
109	  return curseSurcharge + enchantmentSurcharge;
110	};
111	
112	const totalItemSurcharges = (items: Item[]): number =>
113	  items.reduce((total, item) => total + itemSurcharge(item), 0);
114	
115	const isLongStanding = (customer: Customer): boolean =>
116	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
117	
118	// Policy-wide modifiers apply to the policy base premium (the sum of all
119	// item base premiums). Discounts are negative terms in the same sum.
120	const netPolicyModifier = (
121	  basePremium: number,
122	  customer: Customer,
123	  isFollowUpContract: boolean,
124	): number => {
125	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
126	  const loyaltyDiscount = isLongStanding(customer)
127	    ? percentOf(basePremium, LOYALTY_PERCENT)
128	    : 0;
129	  const followUpDiscount = isFollowUpContract
130	    ? percentOf(basePremium, FOLLOW_UP_PERCENT)
131	    : 0;
132	
133	  return firstInsurance - loyaltyDiscount - followUpDiscount;
134	};
135	
136	// The MHPCO insures only what its price list names; anything else is
137	// rejected outright rather than quoted at an unknown rate. Insurability is
138	// derived from the price list itself, so the two cannot drift apart.
139	const assertInsurable = (item: Item): void => {
140	  if (!(item.type in BASE_PREMIUMS)) {
141	    throw new Error(`unknown item type: ${item.type}`);
142	  }
143	};
144	
145	// Rounded in the MHPCO's favour: premiums round up.
146	const quotePremium = (step: QuoteStep, customer: Customer, isFollowUpContract: boolean): number => {
147	  step.items.forEach(assertInsurable);
148	
149	  const basePremium = stepBasePremium(step);
150	
151	  return Math.ceil(
152	    basePremium +
153	      totalItemSurcharges(step.items) +
154	      netPolicyModifier(basePremium, customer, isFollowUpContract) +
155	      PROCESSING_FEE,
156	  );
157	};
158	
159	// The policy's cap is twice the insurance sum of everything it covers.
160	const policyCap = (policy: QuoteStep): number =>
161	  CAP_MULTIPLE *
162	  policy.items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
163	
164	// Components carry no enchantment level, so a missing value is simply not
165	// enchanted enough to trigger the reimbursement clause.
166	const isReimbursedAtHalf = (item: Item): boolean =>
167	  item.enchantment !== undefined &&
168	  item.enchantment >= REIMBURSEMENT_ENCHANTMENT_THRESHOLD;
169	
170	// Special clauses reduce the reimbursed amount BEFORE the deductible is
171	// subtracted: a 1000 G loss on a highly enchanted item reimburses 500, then
172	// pays 400. A deductible applies per damage event, i.e. once per damaged
173	// item. Rounded in the MHPCO's favour: payouts round down.
174	const damagePayout = (damage: Damage, item: Item): number => {
175	  const reimbursed = isReimbursedAtHalf(item)
176	    ? percentOf(damage.amount, HIGH_ENCHANTMENT_REIMBURSEMENT_PERCENT)
177	    : damage.amount;
178	
179	  return Math.floor(reimbursed - DEDUCTIBLE);
180	};
181	
182	const countDamagesByType = (damages: Damage[]): Map<string, number> =>
183	  damages.reduce(
184	    (counts, damage) => counts.set(damage.itemType, (counts.get(damage.itemType) ?? 0) + 1),
185	    new Map<string, number>(),
186	  );
187	
188	// A policy covering one sword answers for one damaged sword, not two: the
189	// whole claim is rejected rather than settled for the part that is covered.
190	const assertNotOverClaimed = (policy: QuoteStep, incident: Incident): void => {
191	  const insured = countByType(policy.items);
192	
193	  countDamagesByType(incident.damages).forEach((damaged, type) => {
194	    if (damaged > (insured.get(type) ?? 0)) {
195	      throw new Error(`more damages than insured items of type: ${type}`);
196	    }
197	  });
198	};
199	
200	// A claim can only be settled against something the policy actually covers.
201	const insuredItemFor = (policy: QuoteStep, damage: Damage): Item => {
202	  const insured = policy.items.find((item) => item.type === damage.itemType);
203	
204	  if (insured === undefined) {
205	    throw new Error(`damaged item not insured: ${damage.itemType}`);
206	  }
207	
208	  return insured;
209	};
210	
211	// A claim is settled against the cap of the policy it names, which is
212	// consumed across successive claims on that policy.
213	const settleClaim = (
214	  step: ClaimStep,
215	  steps: Step[],
216	  capRemaining: Map<number, number>,
217	): { payout: number; remainingCap: number } => {
218	  const policy = steps[step.policy] as QuoteStep;
219	
220	  assertNotOverClaimed(policy, step.incident);
221	
222	  const capBeforeClaim = capRemaining.get(step.policy) ?? policyCap(policy);
223	  const warrantedPayout = step.incident.damages.reduce(
224	    (total, damage) => total + damagePayout(damage, insuredItemFor(policy, damage)),
225	    0,
226	  );
227	
228	  // What the damages warrant is reduced to what the cap still allows.
229	  const payout = Math.min(warrantedPayout, capBeforeClaim);
230	  const remainingCap = capBeforeClaim - payout;
231	
232	  capRemaining.set(step.policy, remainingCap);
233	
234	  return { payout, remainingCap };
235	};
236	
237	export const runScenario = (scenario: unknown): { results: unknown[] } => {
238	  const { customer, steps } = scenario as Scenario;
239	  const capRemaining = new Map<number, number>();
240	
241	  // Every contract after the customer's first is a follow-up.
242	  const results = steps.map((step, index) =>
243	    step.op === "claim"
244	      ? settleClaim(step, steps, capRemaining)
245	      : { premium: quotePremium(step, customer, index > 0) },
246	  );
247	
248	  return { results };
249	};
