// A policy covering one sword answers for one damaged sword, not two: the
// whole claim is rejected rather than settled for the part that is covered.
const assertNotOverClaimed = (policy: QuoteStep, incident: Incident): void => {
  const insured = countByType(policy.items);

  countDamagesByType(incident.damages).forEach((damaged, type) => {
    if (damaged > (insured.get(type) ?? 0)) {
      throw new Error(`more damages than insured items of type: ${type}`);
    }
  });
};

// A claim can only be settled against something the policy actually covers.
const insuredItemFor = (policy: QuoteStep, damage: Damage): Item => {
  const insured = policy.items.find((item) => item.type === damage.itemType);

  if (insured === undefined) {
    throw new Error(`damaged item not insured: ${damage.itemType}`);
  }

  return insured;
};

